<?php $this->setLayout(''); require __DIR__.'/_layout.php'; ?><section class="panel"><p class="muted">Latest 500 invoices across all workspaces.</p><table><thead><tr><th>Invoice</th><th>Workspace</th><th>Customer</th><th>Total</th><th>Fee payer</th><th>Fee</th><th>Status</th><th>Due</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= htmlspecialchars($r['invoice_number']) ?><br><span class="muted"><?= htmlspecialchars($r['public_id']) ?></span></td><td><?= htmlspecialchars($r['workspace_name']) ?></td><td><?= htmlspecialchars($r['customer_name']) ?><br><?= htmlspecialchars($r['customer_email']) ?></td><td><?= htmlspecialchars($r['currency'].' '.number_format((float)$r['total_amount'],2)) ?></td><td><?= htmlspecialchars($r['fee_payer']) ?></td><td><?= htmlspecialchars($r['currency'].' '.number_format((float)$r['platform_fee'],2)) ?></td><td><span class="pill <?= in_array($r['status'],['cancelled','expired','refunded'])?'bad':'' ?>"><?= htmlspecialchars($r['status']) ?></span></td><td><?= htmlspecialchars($r['due_date']??'—') ?></td><td><?= htmlspecialchars($r['created_at']) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="9" class="empty">No invoices found.</td></tr><?php endif; ?></tbody></table></section></main></div></body></html>
